<script setup lang="ts">
import {computed,onBeforeUnmount,reactive,ref} from 'vue'
import {useWorkspace} from '../../app/workspace'
import {createLatestRequests,isCancelled} from '../../shared/api/client'
import FormDialog from '../../shared/components/FormDialog.vue'
import Pagination from '../../shared/components/Pagination.vue'
import {recordNames,types,today,type Profile,type RecordKind,type PersonRecord} from './types'
const props=defineProps<{person:Profile;kind:RecordKind;replaces?:PersonRecord|null;editing?:boolean}>(),emit=defineEmits<{close:[];saved:[]}>()
const {api,command,captureSession}=useWorkspace(),requests=createLatestRequests(api),busy=ref(false),error=ref(''),cases=ref<{id:string;number:string;title:string}[]>([]),casePage=ref(1),caseTotal=ref(0),caseKeyword=ref('')
const form=reactive({record_type:props.replaces?.record_type||Object.keys(types[props.kind])[0],occurred_on:props.replaces?.occurred_on||today(),source:props.replaces?.source||'',document_no:props.editing?props.replaces?.document_no||'':'',basis:props.editing?props.replaces?.basis||'':'',case_id:props.replaces?.case_id||'',expected_end_on:props.editing?props.replaces?.expected_end_on||'':'',details:{...(props.replaces?.details||{})} as Record<string,string>})
type Field={key:string;label:string;type?:string;required?:boolean;options?:Record<string,string>}
const fields=computed<Field[]>(()=>({USE:[{key:'substance',label:'相关物质（依资料填写）'},{key:'finding',label:'事实或认定内容',required:true},{key:'note',label:'补充说明'}],CASE:[{key:'case_nature',label:'关联案件性质',required:true,options:{CRIMINAL:'刑事案件',ADMINISTRATIVE:'行政案件',OTHER:'其他业务'}},{key:'stage',label:'案件阶段',required:true,options:{PROCESSING:'办理中（非刑事）',INVESTIGATION:'侦查',PROSECUTION:'审查起诉',TRIAL:'审判',FINALIZED:'裁判生效',CLOSED:'已结束'}},{key:'allegation',label:'涉嫌事项或在案身份说明',required:true},{key:'outcome',label:'处理结论（有依据时填写）'},{key:'judgment_doc',label:'生效裁判文书号',required:form.record_type==='CONVICTED'},{key:'judgment_effective_on',label:'裁判生效日期',type:'date',required:form.record_type==='CONVICTED'}],MEASURE:[{key:'decision_org',label:form.record_type==='VOLUNTARY'?'接收医疗机构':'决定机关',required:true},{key:'execution_agency',label:'实际执行机构',required:true},{key:'execution_location',label:'执行地点'},{key:'report_due_on',label:'报到 / 执行核对日期',type:'date'},{key:'note',label:'措施说明'}],TEST:[{key:'method',label:'检测方法',required:true},{key:'laboratory',label:'检测机构',required:true},{key:'result',label:'检测结果',required:true,options:{POSITIVE:'阳性',NEGATIVE:'阴性',INCONCLUSIVE:'待定 / 无法判定'}},{key:'next_due_on',label:'后续检测日期',type:'date'},{key:'note',label:'结果说明'}],FOLLOWUP:[{key:'content',label:'随访 / 帮扶内容',required:true},{key:'next_due_on',label:'下次随访日期',type:'date'},{key:'note',label:'补充说明'}]} as Record<RecordKind,Field[]>)[props.kind])
async function loadCases(target=1){busy.value=true;error.value='';try{const result=await requests.latest<{items:typeof cases.value;total:number}>('cases',`/cases?page=${target}&page_size=20&q=${encodeURIComponent(caseKeyword.value.trim())}`);cases.value=result.items;casePage.value=target;caseTotal.value=result.total}catch(e){if(!isCancelled(e))error.value=e instanceof Error?e.message:'案件查询失败'}finally{busy.value=false}}
async function save(){busy.value=true;error.value='';const current=captureSession();try{await command('person-record-'+props.person.id,props.editing?`/person-drafts/records/${props.replaces!.id}/update`:`/person-drafts/${props.person.id}/records`,{person_version:props.person.version,kind:props.kind,record_type:form.record_type,occurred_on:form.occurred_on,source:form.source,document_no:form.document_no,basis:form.basis,details:form.details,case_id:props.kind==='CASE'?form.case_id:null,replaces_id:props.editing?props.replaces?.replaces_id||null:props.replaces?.id||null,...(props.editing?{version:props.replaces!.version}:{}),expected_end_on:props.kind==='MEASURE'?form.expected_end_on||null:null});if(current())emit('saved')}catch(e){if(!isCancelled(e))error.value=e instanceof Error?e.message:'登记失败'}finally{busy.value=false}}
onBeforeUnmount(()=>requests.dispose())
</script>
<template><FormDialog :title="(editing?'补充':replaces?'更正':'登记')+recordNames[kind]" :wide="true" :busy="busy" :error="error" @close="emit('close')"><p class="muted person-hint">{{person.name}} · 新记录保存后待另一名人员核验。{{replaces?'原记录在新记录核验前继续有效，核验后保留为更正历史。':''}}</p><form v-if="kind==='CASE'" class="system-search" @submit.prevent="loadCases(1)"><label>查询本组织案件<input v-model="caseKeyword" maxlength="100"></label><button class="secondary" :disabled="busy">查找案件</button></form><Pagination v-if="kind==='CASE'" :page="casePage" :total="caseTotal" :loading="busy" @change="loadCases($event)"/><form @submit.prevent="save"><div class="person-form-grid"><label>业务类型<select v-model="form.record_type"><option v-for="(name,key) in types[kind]" :key="key" :value="key">{{name}}</option></select></label><label>{{kind==='MEASURE'?'决定日期':kind==='TEST'?'检测日期':'记录日期'}}<input v-model="form.occurred_on" type="date" :max="today()" required></label><label>信息来源<input v-model="form.source" maxlength="200" required></label><label>依据文书 / 报告编号<input v-model="form.document_no" maxlength="200" required></label><label v-if="kind==='CASE'">关联案件<select v-model="form.case_id" required><option value="" disabled>先查询后选择案件</option><option v-if="replaces?.case_id&&!cases.some(row=>row.id===replaces?.case_id)" :value="replaces.case_id">{{replaces.case_number||'原关联案件'}}</option><option v-for="row in cases" :key="row.id" :value="row.id">{{row.number}} · {{row.title}}</option></select></label><label v-if="kind==='MEASURE'">预计结束日期<input v-model="form.expected_end_on" type="date" :min="form.occurred_on"></label></div><label>登记依据与说明<textarea v-model="form.basis" maxlength="2000" required></textarea></label><div class="person-form-grid"><label v-for="field in fields" :key="field.key">{{field.label}}<select v-if="field.options" v-model="form.details[field.key]" :required="field.required"><option value="" disabled>请选择</option><option v-for="(label,value) in field.options" :key="value" :value="value">{{label}}</option></select><input v-else-if="field.type==='date'" v-model="form.details[field.key]" type="date" :required="field.required"><textarea v-else v-model="form.details[field.key]" maxlength="3000" :required="field.required"></textarea></label></div><p v-if="kind==='MEASURE'" class="muted person-hint">实际报到、入所、解除或变更另记执行事件；预计日期只产生核对待办，不自动改变法律状态。</p><button :disabled="busy">保存待核验记录</button></form></FormDialog></template>
